// src/minutes.ts
init_db();
init_repos();
var MINUTES_SYSTEM = '\u4F60\u662F\u529E\u516C\u7FA4\u804A\u7684\u4F1A\u8BAE\u7EAA\u8981\u52A9\u624B\u3002\u8F93\u5165\u662F\u4E00\u6BB5\u6309\u65F6\u95F4\u6392\u5217\u7684\u7FA4\u804A\u8BB0\u5F55\u3002\u8BF7\u8F93\u51FA JSON\uFF1A{"title": \u7B80\u77ED\u4F1A\u8BAE/\u8BA8\u8BBA\u4E3B\u9898, "summary": \u4E24\u4E09\u53E5\u8BDD\u6458\u8981, "decisions": [\u8FBE\u6210\u7684\u7ED3\u8BBA\u6216\u51B3\u5B9A, ...], "action_items": [{"content": \u5F85\u529E\u4E8B\u9879, "assignee_hint": \u8D1F\u8D23\u4EBA(\u539F\u6587\u63D0\u53CA\u6216null), "deadline_hint": \u622A\u6B62\u65F6\u95F4(\u539F\u6587\u63D0\u53CA\u6216null)}]}\u3002\u53EA\u8F93\u51FA JSON\u3002\u6CA1\u6709\u7ED3\u8BBA\u5219 decisions \u4E3A\u7A7A\u6570\u7EC4\uFF0C\u6CA1\u6709\u660E\u786E\u5F85\u529E\u5219 action_items \u4E3A\u7A7A\u6570\u7EC4\uFF0C\u4E0D\u8981\u7F16\u9020\u804A\u5929\u8BB0\u5F55\u91CC\u4E0D\u5B58\u5728\u7684\u5185\u5BB9\u3002';
function rowToDict(r) {
  const ld = (v) => {
    try {
      return v ? typeof v === "string" ? JSON.parse(v) : v : [];
    } catch {
      return [];
    }
  };
  return { ...r, decisions: ld(r.decisions), action_items: ld(r.action_items) };
}
async function generateMinutes(convId, limit = 50) {
  const rows = await query(
    "SELECT * FROM (SELECT * FROM message WHERE conv_id=$1 ORDER BY id DESC LIMIT $2) t ORDER BY id ASC",
    [convId, Math.floor(limit)]
  );
  if (!rows.length) throw new Error("no_messages");
  const transcript = rows.map((r) => `\u3010${r.ts}\u3011${r.sender_name}\uFF1A${r.content}`).join("\n");
  const raw2 = await getLlm()(MINUTES_SYSTEM, transcript, { jsonMode: true, maxTokens: 4096 });
  let data;
  try {
    data = JSON.parse(raw2);
  } catch {
    throw new Error("bad_llm");
  }
  const id = await insertReturningId(
    "INSERT INTO minutes(conv_id, title, summary, decisions, action_items, msg_count) VALUES($1,$2,$3,$4,$5,$6) RETURNING id",
    [
      convId,
      String(data.title ?? "\u672A\u547D\u540D\u7EAA\u8981"),
      String(data.summary ?? ""),
      JSON.stringify(data.decisions ?? []),
      JSON.stringify(data.action_items ?? []),
      rows.length
    ]
  );
  const row = await one("SELECT * FROM minutes WHERE id=$1", [id]);
  await auditLog("user", "minutes_generated", { minutesId: row.id, convId, msgCount: rows.length });
  return rowToDict(row);
}
async function listMinutes(convId) {
  const rows = convId ? await query("SELECT * FROM minutes WHERE conv_id=$1 ORDER BY id DESC", [convId]) : await query("SELECT * FROM minutes ORDER BY id DESC");
  return rows.map(rowToDict);
}
async function getMinutes(minutesId) {
  const row = await one("SELECT * FROM minutes WHERE id=$1", [minutesId]);
  return row ? rowToDict(row) : null;
}
async function minutesToTask(minutesId, index) {
  const m = await getMinutes(minutesId);
  if (!m) return null;
  const items = m.action_items;
  if (!Number.isInteger(index) || index < 0 || index >= items.length) throw new Error("bad_index");
  const item = items[index];
  const tid = await insertTask(
    String(item.content ?? ""),
    `minutes#${minutesId}`,
    item.assignee_hint || null,
    item.deadline_hint || null,
    "pending_confirmation",
    "high",
    String(m.title ?? "")
  );
  await auditLog("user", "minutes_task_created", { minutesId, index, taskId: tid });
  return tid;
}

// src/mine.ts
init_db();
init_repos();
init_memory();
var MINE_SYSTEM = '\u4F60\u662F\u529E\u516C\u7FA4\u804A\u7684\u77E5\u8BC6\u6316\u6398\u52A9\u624B\u3002\u8F93\u5165\u662F\u4E00\u6BB5\u6309\u65F6\u95F4\u6392\u5217\u7684\u7FA4\u804A\u8BB0\u5F55\u7247\u6BB5\u3002\u8BF7\u4ECE\u804A\u5929\u8BB0\u5F55\u91CC\u63D0\u53D6\u4E09\u7C7B\u4FE1\u606F\uFF0C\u8F93\u51FA JSON\uFF1A{"terms":[{"term":\u672F\u8BED,"meaning":\u542B\u4E49}],"aliases":[{"real_name":\u6B63\u540D,"alias":\u79F0\u547C/\u82B1\u540D/\u5916\u53F7}],"tasks":[{"content":\u5F85\u529E\u4E8B\u9879,"assignee_hint":\u8D1F\u8D23\u4EBA(\u539F\u6587\u63D0\u53CA\u6216null),"deadline_hint":\u622A\u6B62\u65F6\u95F4(\u539F\u6587\u63D0\u53CA\u6216null)}],"evidence":{"term":\u539F\u6587\u6458\u5F55,"alias":\u539F\u6587\u6458\u5F55,"task":\u539F\u6587\u6458\u5F55}}\u3002\u53EA\u63D0\u53D6\u804A\u5929\u8BB0\u5F55\u91CC\u771F\u5B9E\u51FA\u73B0\u7684\u5185\u5BB9\uFF0C\u4E0D\u8981\u7F16\u9020\uFF1B\u67D0\u7C7B\u6CA1\u6709\u5C31\u7ED9\u7A7A\u6570\u7EC4\u3002evidence \u5404\u9879\u7ED9\u6700\u6709\u4EE3\u8868\u6027\u7684\u4E00\u53E5\u539F\u6587\uFF08\u6CA1\u6709\u5219 null\uFF09\u3002\u53EA\u8F93\u51FA JSON\u3002';
async function insertCandidate(convId, kind, payload, evidence, msgCount, status = "pending") {
  return insertReturningId(
    "INSERT INTO mine_candidate(conv_id, kind, payload, evidence, msg_count, status) VALUES($1,$2,$3,$4,$5,$6) RETURNING id",
    [convId, kind, JSON.stringify(payload), evidence, msgCount, status]
  );
}
async function termExists(term) {
  return await one("SELECT 1 FROM term WHERE term=$1", [term]) !== null;
}
async function aliasExists(realName, alias) {
  return await one(
    "SELECT 1 FROM alias a JOIN person p ON a.person_id=p.id WHERE p.real_name=$1 AND a.name=$2",
    [realName, alias]
  ) !== null;
}
async function extractBatch(convId, rows, stats) {
  const transcript = rows.map((r) => `\u3010${r.ts}\u3011${r.sender_name}\uFF1A${r.content}`).join("\n");
  let data;
  try {
    data = JSON.parse(await getLlm()(MINE_SYSTEM, transcript, { jsonMode: true, maxTokens: 4096 }));
  } catch {
    stats.skipped_batches += 1;
    return;
  }
  const ev = data.evidence ?? {};
  for (const t of data.terms || []) {
    const term = String(t.term ?? "").trim(), meaning = String(t.meaning ?? "").trim();
    if (!term) continue;
    const status = await termExists(term) ? "duplicate" : "pending";
    await insertCandidate(convId, "term", { term, meaning }, String(ev.term ?? ""), rows.length, status);
    stats.by_kind.term += 1;
  }
  for (const a of data.aliases || []) {
    const real = String(a.real_name ?? "").trim(), alias = String(a.alias ?? "").trim();
    if (!real || !alias) continue;
    const status = await aliasExists(real, alias) ? "duplicate" : "pending";
    await insertCandidate(convId, "alias", { real_name: real, alias }, String(ev.alias ?? ""), rows.length, status);
    stats.by_kind.alias += 1;
  }
  for (const t of data.tasks || []) {
    const content = String(t.content ?? "").trim();
    if (!content) continue;
    await insertCandidate(
      convId,
      "task",
      { content, assignee_hint: t.assignee_hint, deadline_hint: t.deadline_hint },
      String(ev.task ?? ""),
      rows.length
    );
    stats.by_kind.task += 1;
  }
}
async function runMining(convId, limit = 500, batch = 100) {
  const rows = await query(
    "SELECT * FROM (SELECT * FROM message WHERE conv_id=$1 ORDER BY id DESC LIMIT $2) t ORDER BY id ASC",
    [convId, Math.floor(limit)]
  );
  if (!rows.length) throw new Error("no_messages");
  const stats = { skipped_batches: 0, by_kind: { term: 0, alias: 0, task: 0 } };
  const step = Math.max(1, Math.min(Math.floor(batch), 500));
  for (let i = 0; i < rows.length; i += step) {
    await extractBatch(convId, rows.slice(i, i + step), stats);
  }
  await auditLog("user", "mine_run", {
    convId,
    msgCount: rows.length,
    batches: Math.ceil(rows.length / step),
    skippedBatches: stats.skipped_batches,
    byKind: stats.by_kind
  });
  return {
    total: stats.by_kind.term + stats.by_kind.alias + stats.by_kind.task,
    skipped_batches: stats.skipped_batches,
    by_kind: stats.by_kind
  };
}
function rowToDict2(row) {
  let payload = {};
  try {
    payload = row.payload ? JSON.parse(String(row.payload)) : {};
  } catch {
    payload = {};
  }
  return { ...row, payload };
}
async function listCandidates(status = "pending", kind) {
  const conds = [];
  const params = [];
  if (status) {
    conds.push(`status=$${params.length + 1}`);
    params.push(status);
  }
  if (kind) {
    conds.push(`kind=$${params.length + 1}`);
    params.push(kind);
  }
  const where = conds.length ? " WHERE " + conds.join(" AND ") : "";
  const rows = await query(
    `SELECT * FROM mine_candidate${where} ORDER BY id DESC`,
    params
  );
  return rows.map(rowToDict2);
}
async function accept(cand) {
  const kind = cand.kind;
  const payload = cand.payload;
  if (kind === "term") {
    await addTerm(String(payload.term), String(payload.meaning ?? ""), "mined");
    return { term: payload.term };
  }
  if (kind === "alias") {
    const real = String(payload.real_name), alias = String(payload.alias);
    const p = await one("SELECT id FROM person WHERE real_name=$1 ORDER BY id DESC LIMIT 1", [real]);
    let pid;
    if (p) pid = p.id;
    else pid = await insertReturningId("INSERT INTO person(real_name) VALUES($1) RETURNING id", [real]);
    if (!await one("SELECT 1 FROM alias WHERE person_id=$1 AND name=$2", [pid, alias])) {
      await query("INSERT INTO alias(person_id, name) VALUES($1,$2)", [pid, alias]);
    }
    return { personId: pid, alias };
  }
  if (kind === "task") {
    const tid = await insertTask(
      String(payload.content),
      `mine#${cand.id}`,
      payload.assignee_hint ?? null,
      payload.deadline_hint ?? null,
      "pending_confirmation",
      "medium",
      String(cand.evidence ?? "")
    );
    return { taskId: tid };
  }
  throw new Error("bad_kind");
}
async function decideCandidate(cid, action) {
  const row = await one("SELECT * FROM mine_candidate WHERE id=$1", [cid]);
  if (!row) return null;
  const cand = rowToDict2(row);
  if (!["accept", "reject"].includes(action)) throw new Error("bad_action");
  if (cand.status !== "pending") throw new Error("already_decided");
  const result = action === "accept" ? await accept(cand) : {};
  await query(
    "UPDATE mine_candidate SET status=$1, decided_at=NOW(), decided_by='user' WHERE id=$2",
    [action === "accept" ? "accepted" : "rejected", cid]
  );
  await auditLog(
    "user",
    action === "accept" ? "mine_accepted" : "mine_rejected",
    { candidateId: cid, kind: cand.kind, ...result }
  );
  return { id: cid, status: action === "accept" ? "accepted" : "rejected", result };
}

